    edge_color = max(boundary_colors, key=lambda v: sum(grid[r][c] == v for r in range(h) for c in (0, w - 1)))
    marker_colors = {v for row in grid for v in row if v not in (background, edge_color, 4)}
    marker = max(marker_colors, key=lambda v: sum(cell == v for row in grid for cell in row))
